    if (this.valkyrie.getTarget() != null && this.valkyrie.teleportAroundTarget(this.valkyrie.getTarget())) {
        this.teleportTimer = this.valkyrie.getRandom().nextInt(40);
    } else {
        this.teleportTimer -= 20;
    }
}

